package ama.api;
import ama.contract.IdentityContracts.*;import ama.meeting.JdbcImportDrafts;import ama.meeting.JdbcMeetingAccess;import ama.db.TransactionRunner;import ama.task.SubjectFencePort;import com.fasterxml.jackson.core.*;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import javax.sql.DataSource;import org.springframework.web.bind.annotation.*;
@RestController
class ImportDraftController {
 private final JdbcImportDrafts drafts;private final ObjectMapper json=new ObjectMapper(JsonFactory.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).build()).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);
 ImportDraftController(DataSource source,TransactionRunner tx,JdbcMeetingAccess access,ama.task.JdbcSubjectFences fences){drafts=new JdbcImportDrafts(source,tx,access,fences);}
 @GetMapping("/api/v1/meetings/{id}/import-draft") Map<String,Object> read(@PathVariable String id,HttpServletRequest request){return drafts.read(actor(request),id);}
 @PutMapping("/api/v1/meetings/{id}/import-draft") Map<String,Object> save(@PathVariable String id,@RequestBody byte[] bytes,HttpServletRequest request){var body=parse(bytes,Set.of("expectedRevisionToken","orderedFileIds"));var files=body.get("orderedFileIds");if(files==null||!files.isArray()||files.size()>16)throw new IllegalArgumentException("File selection required");var selected=new ArrayList<String>();for(var item:files){if(!item.isTextual())throw new IllegalArgumentException("File ID required");selected.add(item.textValue());}return drafts.save(actor(request),id,key(request),HttpRevisionTokens.expected(body),selected);}
 @PostMapping("/api/v1/meetings/{id}/import-discard") Map<String,Object> discard(@PathVariable String id,@RequestBody byte[] bytes,HttpServletRequest request){var body=parse(bytes,Set.of("expectedRevisionToken"));return drafts.discard(actor(request),id,key(request),HttpRevisionTokens.expected(body));}
 private JsonNode parse(byte[] bytes,Set<String> keys){if(bytes.length>65536)throw new IllegalArgumentException("Import request exceeds budget");try{var body=json.readTree(bytes);if(body==null||!body.isObject()||body.size()!=keys.size())throw new IllegalArgumentException("Invalid import command");body.fieldNames().forEachRemaining(k->{if(!keys.contains(k))throw new IllegalArgumentException("Unknown import field");});return body;}catch(java.io.IOException e){throw new IllegalArgumentException("Invalid import JSON");}}
 private static Actor actor(HttpServletRequest request){return ((ResolvedSession)request.getAttribute(SessionSecurityFilter.SESSION)).actor();}
 private static String key(HttpServletRequest request){var keys=Collections.list(request.getHeaders("Idempotency-Key"));if(keys.size()!=1)throw new IllegalArgumentException("One idempotency key required");return keys.getFirst();}
}
